 4→export interface PlatformConfig {
 5→  max_resumes_per_job: number;
 6→  max_file_size_mb: number;
 7→  resume_retention_days: number;
 8→  payg_per_resume_cost: number;
 9→  topup_min_amount: number;
10→  topup_dodo_product_id: string | null;
11→}
12→
13→const DEFAULTS: PlatformConfig = {
14→  max_resumes_per_job: 10,
15→  max_file_size_mb: 5,
16→  resume_retention_days: 30,
17→  payg_per_resume_cost: 0.07,
18→  topup_min_amount: 1,
19→  topup_dodo_product_id: null,
20→};
21→
22→export const usePlatformConfig = () => {
23→  return useQuery({
24→    queryKey: ["platform_config"],
25→    queryFn: async (): Promise<PlatformConfig> => {
26→      const { data, error } = await supabase
27→        .from("platform_config")
28→        .select("max_resumes_per_job, max_file_size_mb, resume_retention_days, payg_per_resume_cost, topup_min_amount, topup_dodo_product_id")
29→        .limit(1)
30→        .single();
31→      if (error || !data) return DEFAULTS;
32→      return {
33→        ...data,
34→        max_resumes_per_job: Math.min(data.max_resumes_per_job, 20),
35→      };
36→    },
37→    retry: false,
38→    placeholderData: DEFAULTS,
39→  });
40→};
