106→  const loadJobData = async (jobId: string) => {
107→    setSelectedJobId(jobId);
108→    try {
109→      const [resumesRes, resumeListRes] = await Promise.all([
110→        supabase
111→          .from("resumes")
112→          .select("id, filename, file_path, candidate_name, created_at")
113→          .eq("job_id", jobId)
114→          .order("created_at", { ascending: false }),
115→        supabase
116→          .from("resumes")
