140→        .in("resume_id", resumeIds);
141→
142→      const resumeMap = new Map(resumeData.map((r) => [r.id, r]));
143→      const merged: Result[] = (resultData ?? []).map((r: any) => {
144→        const resume = resumeMap.get(r.resume_id);
145→        const parsed = resume?.parsed_json as any;
146→        return {
147→          ...r,
148→          overall_score: r.overall_score ?? 0,
149→          missing_skills: r.missing_skills ?? [],
150→          filename: resume?.filename ?? "Unknown",
151→          file_path: resume?.file_path ?? null,
