156→          experience: parsed?.experience ?? parsed?.work_experience ?? parsed?.work_history ?? [],
157→          education: parsed?.education ?? parsed?.education_history ?? [],
158→        };
159→      });
160→      merged.sort((a, b) => b.overall_score - a.overall_score);
161→      setResults(merged);
162→    } catch (err) {
163→      console.error("Failed to load job data:", err);
164→      toast.error("Failed to load job data");
165→    }
