 2→-- Fix: For users with an active subscription plan, move the plan's credit allotment
 3→-- from topup_credits to subscription_credits.
 4→-- This corrects data from a previous migration that lumped all credits into topup_credits.
 5→UPDATE profiles p
 6→SET subscription_credits = LEAST(pl.credits, p.topup_credits),
 7→    topup_credits = p.topup_credits - LEAST(pl.credits, p.topup_credits)
 8→FROM plans pl
 9→WHERE p.plan IS NOT NULL
10→  AND p.plan != 'free'
11→  AND pl.name = p.plan
12→  AND pl.active = true
13→  AND p.subscription_credits = 0
14→  AND p.topup_credits > 0;
